# Updated TenantShipmentPrintView from iroad_tenants/sdsdsd.txt; existing definition is kept above.
class TenantShipmentPrintView(View):
    template_name = 'iroad_tenants/Printing-Templates/shipment_print_dynamic.html'

    def get(self, request, shipment_id):
        auth_payload = _require_tenant_jwt_auth(request)
        if auth_payload is None:
            return JsonResponse({'error': 'Unauthorized'}, status=401)
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            return JsonResponse({'error': 'Tenant session is not active'}, status=401)
        try:
            shipment = TenantShipment.objects.select_related('truck').filter(pk=shipment_id).first()
            if not shipment:
                return JsonResponse({'error': 'Shipment not found'}, status=404)
            booking = shipment.booking if shipment.booking_id else None
            html_content = _render_printing_template_html(
                'shipment_print_dynamic.html',
                {
                    'shipment': shipment,
                    'booking': booking,
                    'cod_payment_status': (
                        shipment.collection_status
                        if shipment.cod_amount and shipment.cod_amount > 0
                        else 'Not Applicable'
                    ),
                    'additional_charges': shipment.total_additional_charges,
                },
            )
            pdf_content = _render_pdf_from_html_bytes(html_content, page_size='A4', margin_cm='0.2')
            filename = _safe_pdf_filename(shipment.shipment_no, 'SH.pdf')
            return _inline_pdf_response(pdf_content, filename)
        except Exception:
            logger.exception('Tenant shipment print stream failed')
            return JsonResponse({'error': 'Failed to render print PDF'}, status=500)
        finally:
            connection.set_schema_to_public()

# Updated operation management views from iroad_tenants/sdsdsd.txt; existing stubs are kept above.
def _tenant_booking_form_options_context(tenant_registry, booking=None):
    available_tables = set(connection.introspection.table_names())
    has_table = available_tables.__contains__
    client_accounts = list(
        TenantClientAccount.objects.filter(
            status=TenantClientAccount.Status.ACTIVE,
        ).order_by('account_no')
    )
    price_lists = list(
        TenantPriceList.objects.filter(
            status=TenantPriceList.Status.ACTIVE,
        ).select_related('client_account').order_by('price_list_code')
    )
    service_items = list(
        TenantServiceItemMaster.objects.filter(
            status=TenantServiceItemMaster.Status.ACTIVE,
        ).order_by('service_code')
    )
    routes = []
    if has_table('tenant_route_master') and has_table('tenant_location_master'):
        routes = list(
            TenantRouteMaster.eligible_for_operational_use.select_related(
                'origin_point',
                'destination_point',
            ).order_by('route_code')
        )

    loading_addresses = []
    delivery_addresses = []
    if has_table('tenant_address_master'):
        loading_addresses = list(
            TenantAddressMaster.active_objects.select_related('client_account')
            .filter(
                Q(address_category=TenantAddressMaster.AddressCategory.PICKUP_ADDRESS)
                | Q(address_category=TenantAddressMaster.AddressCategory.BOTH)
            )
            .order_by('address_code')
        )
        delivery_addresses = list(
            TenantAddressMaster.active_objects.select_related('client_account')
            .filter(
                Q(address_category=TenantAddressMaster.AddressCategory.DELIVERY_ADDRESS)
                | Q(address_category=TenantAddressMaster.AddressCategory.BOTH)
            )
            .order_by('address_code')
        )

    cargo_items = []
    if has_table('tenant_cargo_master'):
        cargo_items = list(
            TenantCargoMaster.active_objects.select_related('client_account').order_by('cargo_code')
        )
    trucks = (
        list(TruckMaster.active_objects.select_related('default_driver_id').order_by('truck_code'))
        if has_table('tenant_truck_master')
        else []
    )
    drivers = list(DriverMaster.active_objects.order_by('driver_code'))

    price_list_service_map = {}
    if has_table('tenant_price_list_service_line'):
        for line in TenantPriceListServiceLine.objects.select_related('price_list', 'service_item').all():
            price_list_service_map.setdefault(str(line.price_list_id), set()).add(str(line.service_item_id))
    if has_table('tenant_price_list_trip_line'):
        for line in TenantPriceListTripLine.objects.select_related('price_list', 'trip_service').all():
            price_list_service_map.setdefault(str(line.price_list_id), set()).add(str(line.trip_service_id))

    service_item_price_lists = {}
    for price_list_id, service_ids in price_list_service_map.items():
        for service_id in service_ids:
            service_item_price_lists.setdefault(service_id, set()).add(price_list_id)

    booking_service_options = []
    for service_item in service_items:
        service_key = str(service_item.service_item_id)
        booking_service_options.append(
            {
                'service_item_id': service_key,
                'service_code': service_item.service_code,
                'english_name': service_item.english_name,
                'service_type': service_item.service_type,
                'route_id': str(service_item.route_id or ''),
                'base_sell_price': str(service_item.sell_price or '0'),
                'price_list_ids_csv': ','.join(sorted(list(service_item_price_lists.get(service_key, set())))),
            }
        )

    service_sell_overrides = {}
    trip_sell_overrides = {}
    if has_table('tenant_price_list_service_line'):
        for line in TenantPriceListServiceLine.objects.select_related('price_list', 'service_item').all():
            service_sell_overrides.setdefault(str(line.price_list_id), {})[str(line.service_item_id)] = str(line.sell_price_override)
    if has_table('tenant_price_list_trip_line'):
        for line in TenantPriceListTripLine.objects.select_related('price_list', 'trip_service').all():
            pl_map = trip_sell_overrides.setdefault(str(line.price_list_id), {})
            pl_map.setdefault(str(line.trip_service_id), {})[str(line.trip_type)] = str(line.sell_price_override)

    booking_line_status_values = _tenant_booking_line_status_map(booking)
    form_data = {}
    if booking is not None:
        form_data = {
            'booking_date': booking.booking_date.isoformat() if booking.booking_date else '',
            'execution_date': booking.execution_date.isoformat() if booking.execution_date else '',
            'booking_status': booking.booking_status,
            'pod_type': booking.pod_type,
            'pod_status': booking.pod_status,
            'sourcing_mode': booking.sourcing_mode or 'Internal',
            'client_account': str(booking.client_account_id or ''),
            'sales_order_no': str(booking.price_list_id or ''),
            'service_lookup': str(booking.service_item_id or ''),
            'route_lookup': f'{booking.route_id}|{booking.route_direction}' if booking.route_id else '',
            'order_type': booking.order_type,
            'trip_type': booking.trip_type,
            'sell_price': str(booking.sell_price or ''),
            'booking_line_truck_1': str(booking.assigned_truck_id or ''),
            'booking_line_driver_1': str(booking.assigned_driver_id or ''),
            'booking_line_cod_amount_1': str(booking.booking_line_cod_amount or ''),
            'booking_line_pod_doc_count_1': str(booking.booking_line_pod_doc_count or ''),
            'booking_line_truck_2': str(booking.booking_line_backload_truck_id or ''),
            'booking_line_driver_2': str(booking.booking_line_backload_driver_id or ''),
            'booking_line_cod_amount_2': str(booking.booking_line_backload_cod_amount or ''),
            'booking_line_pod_doc_count_2': str(booking.booking_line_backload_pod_doc_count or ''),
            'loading_booking_item_1': booking.loading_booking_item,
            'loading_address_1': str(booking.loading_address_id or ''),
            'delivery_booking_item_1': booking.delivery_booking_item,
            'delivery_address_1': str(booking.delivery_address_id or ''),
            'cargo_booking_item_1': booking.cargo_booking_item,
            'cargo_id_1': str(booking.cargo_id or ''),
            'cargo_weight_1': str(booking.cargo_weight or ''),
            'cargo_unit_1': booking.cargo_unit,
            'cargo_qty_1': str(booking.cargo_qty or ''),
            'total_cargo_qty': str(booking.total_cargo_qty or '0'),
            'total_cargo_weight': str(booking.total_cargo_weight or '0.00'),
            'container_no': booking.container_no,
            'booking_instructions': booking.booking_instructions,
        }

    return {
        'booking_client_accounts': client_accounts,
        'booking_price_lists': price_lists,
        'booking_service_items': service_items,
        'booking_service_options': booking_service_options,
        'booking_routes': routes,
        'booking_loading_addresses': loading_addresses,
        'booking_delivery_addresses': delivery_addresses,
        'booking_cargo_items': cargo_items,
        'booking_trucks': trucks,
        'booking_drivers': drivers,
        'booking_service_sell_overrides': service_sell_overrides,
        'booking_trip_sell_overrides': trip_sell_overrides,
        'booking_line_status_values': booking_line_status_values,
        'booking_line_type_options': ('Outbound', 'Backload'),
        'booking_order_type_options': ('Credit', 'COD'),
        'booking_trip_type_options': ('One-Way', 'Round'),
        'booking_pod_type_options': ('Signature', 'Photo', 'Digital'),
        'booking_pod_status_options': ('Pending', 'Received', 'Verified'),
        'booking_form_data': form_data,
        'tenant_schema_name': tenant_registry.schema_name,
    }


def _tenant_booking_shipment_line_key(booking, booking_item_type):
    line_type = (booking_item_type or '').strip().lower()
    if booking is not None and booking.trip_type == 'Round' and line_type in {'backload', 'inbound'}:
        return 'Backload'
    return 'Outbound'


def _tenant_booking_line_status_from_shipment(shipment):
    if shipment.shipment_status == TenantShipment.ShipmentStatus.CREATED:
        return 'Shipment Created'
    if shipment.shipment_status == TenantShipment.ShipmentStatus.IN_TRANSIT:
        return 'In Transit'
    if shipment.shipment_status == TenantShipment.ShipmentStatus.DELIVERED:
        if shipment.pod_status == TenantShipment.PodStatus.COMPLIANT:
            return 'POD Complete'
        return 'Delivered'
    if shipment.shipment_status == TenantShipment.ShipmentStatus.CLOSED:
        return 'Closed'
    if shipment.shipment_status == TenantShipment.ShipmentStatus.CANCELLED:
        return 'Cancelled'
    return shipment.shipment_status or 'Shipment Created'


def _tenant_booking_line_status_map(booking):
    status_map = {'Outbound': 'Draft', 'Backload': 'Draft'}
    if booking is None or not (booking.booking_no or '').strip():
        return status_map
    shipments = (
        TenantShipment.objects.filter(booking_id=booking.booking_id)
        .order_by('created_at', 'updated_at')
    )
    for shipment in shipments:
        line_key = _tenant_booking_shipment_line_key(booking, shipment.booking_item_type)
        status_map[line_key] = _tenant_booking_line_status_from_shipment(shipment)
    return status_map


def _tenant_booking_route_from_lookup(route_lookup):
    route_lookup = (route_lookup or '').strip()
    route_id, route_direction = (route_lookup.split('|', 1) + ['forward'])[:2] if route_lookup else ('', 'forward')
    route = TenantRouteMaster.objects.filter(route_id=route_id).select_related(
        'origin_point',
        'destination_point',
    ).first()
    route_display = ''
    if route:
        forward_label = f'{route.origin_point.display_label} To {route.destination_point.display_label}'
        reverse_label = f'{route.destination_point.display_label} To {route.origin_point.display_label}'
        route_display = reverse_label if route_direction == 'reverse' else forward_label
    return route, route_direction, route_display


def _decimal_from_request(request, *field_names, default='0'):
    raw_value = ''
    for field_name in field_names:
        raw_value = (request.POST.get(field_name) or '').strip()
        if raw_value:
            break
    if not raw_value:
        raw_value = default
    try:
        return Decimal(raw_value)
    except Exception:
        return Decimal(default)


def _int_from_request(request, *field_names, default=0):
    raw_value = ''
    for field_name in field_names:
        raw_value = (request.POST.get(field_name) or '').strip()
        if raw_value:
            break
    try:
        return int(raw_value)
    except Exception:
        return default


def _first_post_value(request, *field_names):
    for field_name in field_names:
        raw_value = (request.POST.get(field_name) or '').strip()
        if raw_value:
            return raw_value
    return ''


def _tenant_booking_normalize_sourcing_mode(raw_value):
    value = (raw_value or '').strip()
    if value in {'External', 'Out-Source', 'Outsource', 'OUT_SOURCE'}:
        return 'External'
    return 'Internal'


def _tenant_booking_truck_matches_sourcing(truck, sourcing_mode):
    if truck is None:
        return True
    if sourcing_mode == 'External':
        return truck.sourcing_mode == TruckMaster.SourcingMode.OUT_SOURCE
    return truck.sourcing_mode == TruckMaster.SourcingMode.IN_SOURCE


def _tenant_booking_derive_sell_price(price_list, service_item, trip_type, has_table):
    if price_list is None or service_item is None:
        return None
    trip_type = (trip_type or '').strip()
    if service_item.service_type == 'Trip':
        if has_table('tenant_price_list_trip_line'):
            line = TenantPriceListTripLine.objects.filter(
                price_list=price_list,
                trip_service=service_item,
                trip_type=trip_type,
            ).first()
            if line and line.sell_price_override is not None:
                return Decimal(line.sell_price_override)
        for fallback_trip in (trip_type, 'One-Way', 'Round'):
            if not fallback_trip:
                continue
            if has_table('tenant_price_list_trip_line'):
                line = TenantPriceListTripLine.objects.filter(
                    price_list=price_list,
                    trip_service=service_item,
                    trip_type=fallback_trip,
                ).first()
                if line and line.sell_price_override is not None:
                    return Decimal(line.sell_price_override)
    elif has_table('tenant_price_list_service_line'):
        line = TenantPriceListServiceLine.objects.filter(
            price_list=price_list,
            service_item=service_item,
        ).first()
        if line and line.sell_price_override is not None:
            return Decimal(line.sell_price_override)
    if service_item.sell_price is not None:
        return Decimal(service_item.sell_price)
    return Decimal('0')


def _tenant_booking_scheduling_conflict(*, execution_date, truck, driver, exclude_booking_id=None):
    if execution_date is None or truck is None or driver is None:
        return False
    qs = TenantBooking.objects.filter(
        booking_status=TenantBooking.Status.CONFIRMED,
        execution_date=execution_date,
        assigned_truck=truck,
        assigned_driver=driver,
    )
    if exclude_booking_id:
        qs = qs.exclude(pk=exclude_booking_id)
    return qs.exists()


def _tenant_booking_validate_submission(request, *, booking_id=None, has_table=None):
    """BK-001 matched-field validations (Draft save vs Confirm)."""
    if has_table is None:
        has_table = set(connection.introspection.table_names()).__contains__

    errors = []
    booking_status = (request.POST.get('booking_status') or TenantBooking.Status.DRAFT).strip()
    is_confirm = booking_status == TenantBooking.Status.CONFIRMED
    sourcing_mode = _tenant_booking_normalize_sourcing_mode(request.POST.get('sourcing_mode'))
    order_type = (request.POST.get('order_type') or '').strip()

    client = TenantClientAccount.objects.filter(
        account_id=(request.POST.get('client_account') or '').strip(),
        status=TenantClientAccount.Status.ACTIVE,
    ).first()
    if client is None:
        errors.append('Please select a valid client account.')

    price_list = None
    if client is not None:
        price_list = TenantPriceList.objects.filter(
            price_list_id=(request.POST.get('sales_order_no') or '').strip(),
            client_account=client,
            status=TenantPriceList.Status.ACTIVE,
        ).first()
        if is_confirm and price_list is None:
            errors.append('Please select a valid price list for the client account.')

    service_item = None
    if (request.POST.get('service_lookup') or '').strip():
        service_item = TenantServiceItemMaster.objects.filter(
            service_item_id=(request.POST.get('service_lookup') or '').strip(),
            status=TenantServiceItemMaster.Status.ACTIVE,
        ).first()
        if is_confirm and service_item is None:
            errors.append('Please select a valid service.')
        if is_confirm and price_list and service_item and has_table('tenant_price_list_service_line'):
            linked_service_ids = set()
            if has_table('tenant_price_list_service_line'):
                linked_service_ids.update(
                    TenantPriceListServiceLine.objects.filter(price_list=price_list).values_list(
                        'service_item_id', flat=True
                    )
                )
            if has_table('tenant_price_list_trip_line'):
                linked_service_ids.update(
                    TenantPriceListTripLine.objects.filter(price_list=price_list).values_list(
                        'trip_service_id', flat=True
                    )
                )
            if linked_service_ids and service_item.service_item_id not in linked_service_ids:
                errors.append('Selected service is not linked to the selected price list.')

    trip_type = (request.POST.get('trip_type') or '').strip()
    if is_confirm and not trip_type:
        errors.append('Trip type is required before confirming a booking.')

    route_lookup = (request.POST.get('route_lookup') or '').strip()
    route, route_direction, route_display = _tenant_booking_route_from_lookup(route_lookup)
    if is_confirm and not route_lookup:
        errors.append('Route is required before confirming a booking.')
    if is_confirm and route_lookup and route is None:
        errors.append('Please select a valid route.')

    execution_date = parse_date((request.POST.get('execution_date') or '').strip())
    if is_confirm and execution_date is None:
        errors.append('Execution date is required before confirming a booking.')

    truck, driver = _tenant_booking_line_assignment(request, 1, has_table)
    backload_truck, backload_driver = _tenant_booking_line_assignment(request, 2, has_table)
    if is_confirm:
        if truck is None:
            errors.append('Truck is required before confirming a booking.')
        if driver is None:
            errors.append('Driver is required before confirming a booking.')
        if trip_type == 'Round':
            if backload_truck is None:
                errors.append('Backload truck is required for round-trip bookings before confirm.')
            if backload_driver is None:
                errors.append('Backload driver is required for round-trip bookings before confirm.')
        if truck and not _tenant_booking_truck_matches_sourcing(truck, sourcing_mode):
            errors.append('Selected truck does not match the booking sourcing mode.')
        if backload_truck and not _tenant_booking_truck_matches_sourcing(backload_truck, sourcing_mode):
            errors.append('Selected backload truck does not match the booking sourcing mode.')

    loading_address_id = _first_post_value(request, 'loading_address_1')
    delivery_address_id = _first_post_value(request, 'delivery_address_1')
    if is_confirm:
        if not loading_address_id:
            errors.append('Loading address is required before confirming a booking.')
        elif has_table('tenant_address_master'):
            loading_ok = TenantAddressMaster.active_objects.filter(
                pk=loading_address_id,
                client_account=client,
            ).exists()
            if client and not loading_ok:
                errors.append('Loading address must belong to the selected client account.')
        if not delivery_address_id:
            errors.append('Delivery address is required before confirming a booking.')
        elif has_table('tenant_address_master'):
            delivery_ok = TenantAddressMaster.active_objects.filter(
                pk=delivery_address_id,
                client_account=client,
            ).exists()
            if client and not delivery_ok:
                errors.append('Delivery address must belong to the selected client account.')

    cargo_id = _first_post_value(request, 'cargo_id_1', 'cargo_id', 'cargo')
    cargo_qty = _decimal_from_request(request, 'cargo_qty_1')
    cargo_weight = _decimal_from_request(request, 'cargo_weight_1')
    if is_confirm:
        if not cargo_id:
            errors.append('Cargo item is required before confirming a booking.')
        elif has_table('tenant_cargo_master') and client:
            cargo_ok = TenantCargoMaster.active_objects.filter(
                pk=cargo_id,
                client_account=client,
            ).exists()
            if not cargo_ok:
                errors.append('Cargo item must belong to the selected client account.')
        if cargo_qty <= 0:
            errors.append('Cargo quantity must be greater than zero.')
        if cargo_weight < 0:
            errors.append('Cargo weight (ton) cannot be negative.')

    if is_confirm and price_list and service_item:
        derived_sell = _tenant_booking_derive_sell_price(
            price_list,
            service_item,
            trip_type,
            has_table,
        )
        if derived_sell is None:
            errors.append('Unable to derive sell price from the selected price list and service.')

    if is_confirm and sourcing_mode == 'External':
        if not _first_post_value(request, 'vendor_account', 'purchase_order_no', 'purchase_order_line'):
            errors.append(
                'External sourcing requires vendor and purchase order details. '
                'Purchase order fields are not on this form yet; save as Draft or use Internal sourcing.'
            )

    if is_confirm and sourcing_mode == 'External' and order_type == 'COD':
        errors.append(
            'COD bookings with external sourcing require a compatible COD or prepaid purchase order. '
            'Confirm is blocked until purchase order fields are available.'
        )

    if is_confirm and execution_date and truck and driver:
        if _tenant_booking_scheduling_conflict(
            execution_date=execution_date,
            truck=truck,
            driver=driver,
            exclude_booking_id=booking_id,
        ):
            errors.append(
                'Another confirmed booking already uses the same execution date, truck, and driver.'
            )

    return errors, {
        'client': client,
        'price_list': price_list,
        'service_item': service_item,
        'route': route,
        'route_direction': route_direction,
        'route_display': route_display,
        'execution_date': execution_date,
        'sourcing_mode': sourcing_mode,
        'derived_sell_price': _tenant_booking_derive_sell_price(
            price_list,
            service_item,
            trip_type,
            has_table,
        ) if price_list and service_item else Decimal('0'),
        'truck': truck,
        'driver': driver,
    }


def _tenant_booking_line_assignment(request, line_no, has_table):
    truck = None
    truck_id = _first_post_value(request, f'booking_line_truck_{line_no}')
    if line_no == 1 and not truck_id:
        truck_id = _first_post_value(request, 'assigned_truck_id', 'assigned_truck')
    if truck_id and has_table('tenant_truck_master'):
        truck = TruckMaster.objects.select_related('default_driver_id').filter(
            pk=truck_id
        ).first()

    driver = None
    driver_id = _first_post_value(request, f'booking_line_driver_{line_no}')
    if line_no == 1 and not driver_id:
        driver_id = _first_post_value(request, 'assigned_driver_id', 'assigned_driver')
    if driver_id and has_table('tenant_driver_master'):
        driver = DriverMaster.objects.filter(
            pk=driver_id
        ).first()
    if driver is None and truck and truck.default_driver_id:
        driver = truck.default_driver_id
    if truck is None and driver and has_table('tenant_truck_master'):
        truck = TruckMaster.active_objects.select_related('default_driver_id').filter(
            default_driver_id=driver,
        ).order_by('truck_code').first()

    return truck, driver


def _tenant_booking_extra_payload(request):
    available_tables = set(connection.introspection.table_names())
    has_table = available_tables.__contains__
    truck, driver = _tenant_booking_line_assignment(request, 1, has_table)
    backload_truck, backload_driver = _tenant_booking_line_assignment(request, 2, has_table)
    loading_address = None
    loading_address_id = _first_post_value(request, 'loading_address_1')
    if loading_address_id and has_table('tenant_address_master'):
        loading_address = TenantAddressMaster.active_objects.filter(
            pk=loading_address_id,
        ).first()
    delivery_address = None
    delivery_address_id = _first_post_value(request, 'delivery_address_1')
    if delivery_address_id and has_table('tenant_address_master'):
        delivery_address = TenantAddressMaster.active_objects.filter(
            pk=delivery_address_id,
        ).first()
    cargo = None
    cargo_id = _first_post_value(request, 'cargo_id_1', 'cargo_id', 'cargo')
    if cargo_id and has_table('tenant_cargo_master'):
        cargo = TenantCargoMaster.objects.filter(
            pk=cargo_id
        ).first()
    cargo_weight = _decimal_from_request(request, 'cargo_weight_1')
    cargo_qty = _decimal_from_request(request, 'cargo_qty_1')
    cargo_unit = (request.POST.get('cargo_unit_1') or '').strip()
    if cargo:
        if not cargo_unit:
            cargo_unit = cargo.uom or ''
    cargo_booking_item = (request.POST.get('cargo_booking_item_1') or '').strip()
    if not cargo_booking_item and (request.POST.get('trip_type') or '').strip():
        cargo_booking_item = 'Outbound'
    total_cargo_weight = cargo_weight
    return {
        'assigned_truck': truck,
        'assigned_driver': driver,
        'booking_line_cod_amount': _decimal_from_request(
            request,
            'booking_line_cod_amount_1',
        ),
        'booking_line_pod_doc_count': _int_from_request(
            request,
            'booking_line_pod_doc_count_1',
        ),
        'booking_line_backload_truck': backload_truck,
        'booking_line_backload_driver': backload_driver,
        'booking_line_backload_cod_amount': _decimal_from_request(
            request,
            'booking_line_cod_amount_2',
        ),
        'booking_line_backload_pod_doc_count': _int_from_request(
            request,
            'booking_line_pod_doc_count_2',
        ),
        'loading_booking_item': (request.POST.get('loading_booking_item_1') or '').strip(),
        'loading_address': loading_address,
        'delivery_booking_item': (request.POST.get('delivery_booking_item_1') or '').strip(),
        'delivery_address': delivery_address,
        'cargo_booking_item': cargo_booking_item,
        'cargo': cargo,
        'cargo_weight': cargo_weight,
        'cargo_unit': cargo_unit,
        'cargo_qty': cargo_qty,
        'total_cargo_qty': cargo_qty,
        'total_cargo_weight': total_cargo_weight,
        'container_no': (request.POST.get('container_no') or '').strip(),
        'booking_instructions': (request.POST.get('booking_instructions') or '').strip(),
    }


class TenantOperationBookingCreateView(View):
    """Render booking create page."""

    template_name = 'iroad_tenants/Operation_management/Booking/Booking.html'

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        if not context.get('is_tenant_admin') and not context.get('can_view_booking'):
            messages.error(request, 'You do not have permission to view Booking.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_dashboard')
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            available_tables = set(connection.introspection.table_names())
            has_table = available_tables.__contains__

            client_accounts = list(
                TenantClientAccount.objects.filter(
                    status=TenantClientAccount.Status.ACTIVE,
                ).order_by('account_no')
            )
            price_lists = list(
                TenantPriceList.objects.filter(
                    status=TenantPriceList.Status.ACTIVE,
                ).select_related('client_account').order_by('price_list_code')
            )
            service_items = list(
                TenantServiceItemMaster.objects.filter(
                    status=TenantServiceItemMaster.Status.ACTIVE,
                ).order_by('service_code')
            )

            routes = []
            if has_table('tenant_route_master') and has_table('tenant_location_master'):
                routes = list(
                    TenantRouteMaster.eligible_for_operational_use.select_related(
                        'origin_point',
                        'destination_point',
                    ).order_by('route_code')
                )

            loading_addresses = []
            delivery_addresses = []
            if has_table('tenant_address_master'):
                loading_addresses = list(
                    TenantAddressMaster.active_objects.select_related('client_account')
                    .filter(
                        Q(address_category=TenantAddressMaster.AddressCategory.PICKUP_ADDRESS)
                        | Q(address_category=TenantAddressMaster.AddressCategory.BOTH)
                    )
                    .order_by('address_code')
                )
                delivery_addresses = list(
                    TenantAddressMaster.active_objects.select_related('client_account')
                    .filter(
                        Q(address_category=TenantAddressMaster.AddressCategory.DELIVERY_ADDRESS)
                        | Q(address_category=TenantAddressMaster.AddressCategory.BOTH)
                    )
                    .order_by('address_code')
                )

            cargo_items = []
            if has_table('tenant_cargo_master'):
                cargo_items = list(
                    TenantCargoMaster.active_objects.select_related('client_account').order_by('cargo_code')
                )

            trucks = []
            if has_table('tenant_truck_master'):
                trucks = list(
                    TruckMaster.active_objects.select_related('default_driver_id').order_by('truck_code')
                )
            driver_ids = sorted(
                {
                    str(truck.default_driver_id).strip()
                    for truck in trucks
                    if truck.default_driver_id
                }
            )

            price_list_service_map = {}
            if has_table('tenant_price_list_service_line'):
                for line in TenantPriceListServiceLine.objects.select_related(
                    'price_list',
                    'service_item',
                ).all():
                    service_ids = price_list_service_map.setdefault(str(line.price_list_id), set())
                    service_ids.add(str(line.service_item_id))
            if has_table('tenant_price_list_trip_line'):
                for line in TenantPriceListTripLine.objects.select_related(
                    'price_list',
                    'trip_service',
                ).all():
                    service_ids = price_list_service_map.setdefault(str(line.price_list_id), set())
                    service_ids.add(str(line.trip_service_id))

            service_item_price_lists = {}
            for price_list_id, service_ids in price_list_service_map.items():
                for service_id in service_ids:
                    service_item_price_lists.setdefault(service_id, set()).add(price_list_id)

            booking_service_options = []
            for service_item in service_items:
                service_key = str(service_item.service_item_id)
                linked_price_lists = sorted(list(service_item_price_lists.get(service_key, set())))
                booking_service_options.append(
                    {
                        'service_item_id': service_key,
                        'service_code': service_item.service_code,
                        'english_name': service_item.english_name,
                        'service_type': service_item.service_type,
                        'route_id': str(service_item.route_id or ''),
                        'base_sell_price': str(service_item.sell_price or '0'),
                        'price_list_ids_csv': ','.join(linked_price_lists),
                    }
                )

            service_sell_overrides = {}
            trip_sell_overrides = {}
            if has_table('tenant_price_list_service_line'):
                for line in TenantPriceListServiceLine.objects.select_related(
                    'price_list',
                    'service_item',
                ).all():
                    pl_map = service_sell_overrides.setdefault(str(line.price_list_id), {})
                    pl_map[str(line.service_item_id)] = str(line.sell_price_override)
            if has_table('tenant_price_list_trip_line'):
                for line in TenantPriceListTripLine.objects.select_related(
                    'price_list',
                    'trip_service',
                ).all():
                    pl_map = trip_sell_overrides.setdefault(str(line.price_list_id), {})
                    svc_map = pl_map.setdefault(str(line.trip_service_id), {})
                    svc_map[str(line.trip_type)] = str(line.sell_price_override)

            context.update(
                {
                    'booking_creation_date': timezone.localdate(),
                    'preview_booking_no': _preview_next_auto_number_for_form(
                        form_code=BOOKING_AUTO_FORM_CODE,
                        form_label=BOOKING_AUTO_FORM_LABEL,
                        prefix=BOOKING_REF_PREFIX,
                    ),
                    'booking_client_accounts': client_accounts,
                    'booking_price_lists': price_lists,
                    'booking_service_items': service_items,
                    'booking_service_options': booking_service_options,
                    'booking_routes': routes,
                    'booking_loading_addresses': loading_addresses,
                    'booking_delivery_addresses': delivery_addresses,
                    'booking_cargo_items': cargo_items,
                    'booking_trucks': trucks,
                    'booking_drivers': list(DriverMaster.active_objects.order_by('driver_code')),
                    'booking_service_sell_overrides': service_sell_overrides,
                    'booking_trip_sell_overrides': trip_sell_overrides,
                    'booking_line_status_values': {'Outbound': 'Draft', 'Backload': 'Draft'},
                    'booking_line_type_options': ('Outbound', 'Backload'),
                    'booking_order_type_options': ('Credit', 'COD'),
                    'booking_trip_type_options': ('One-Way', 'Round'),
                    'booking_pod_type_options': ('Signature', 'Photo', 'Digital'),
                    'booking_pod_status_options': ('Pending', 'Received', 'Verified'),
                    'booking_form_data': {},
                    'booking_is_edit': False,
                    'tenant_schema_name': tenant_registry.schema_name,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()

    def post(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        if not context.get('is_tenant_admin') and not context.get('can_view_booking'):
            messages.error(request, 'You do not have permission to save Booking.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_dashboard')

        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            available_tables = set(connection.introspection.table_names())
            has_table = available_tables.__contains__
            validation_errors, validated = _tenant_booking_validate_submission(
                request,
                has_table=has_table,
            )
            if validation_errors:
                for error in validation_errors:
                    messages.error(request, error, extra_tags='tenant')
                return _tenant_redirect(request, 'iroad_tenants:tenant_operation_booking_create')

            client = validated['client']
            price_list = validated['price_list']
            service_item = validated['service_item']
            route = validated['route']
            route_direction = validated['route_direction']
            route_display = validated['route_display']
            execution_date = validated['execution_date']
            sell_price = validated['derived_sell_price']
            sourcing_mode = validated['sourcing_mode']

            booking_date = parse_date((request.POST.get('booking_date') or '').strip()) or timezone.localdate()
            extra_payload = _tenant_booking_extra_payload(request)

            with db_transaction.atomic():
                booking_no, booking_sequence = _next_auto_number_for_form(
                    form_code=BOOKING_AUTO_FORM_CODE,
                    form_label=BOOKING_AUTO_FORM_LABEL,
                    prefix=BOOKING_REF_PREFIX,
                )
                booking = TenantBooking.objects.create(
                    booking_no=booking_no,
                    booking_sequence=booking_sequence,
                    creation_date=timezone.localdate(),
                    booking_date=booking_date,
                    execution_date=execution_date,
                    booking_status=(request.POST.get('booking_status') or TenantBooking.Status.DRAFT).strip(),
                    client_account=client,
                    price_list=price_list,
                    service_item=service_item,
                    route=route,
                    route_direction=route_direction,
                    route_display=route_display,
                    order_type=(request.POST.get('order_type') or '').strip(),
                    trip_type=(request.POST.get('trip_type') or '').strip(),
                    sell_price=sell_price,
                    sourcing_mode=sourcing_mode,
                    pod_type=(request.POST.get('pod_type') or '').strip(),
                    pod_status=(request.POST.get('pod_status') or '').strip(),
                    **extra_payload,
                    created_by_label=(context.get('display_name') or '').strip(),
                )
                if request.FILES.get('booking_attachment'):
                    booking.booking_attachment = request.FILES['booking_attachment']
                    booking.save(update_fields=['booking_attachment', 'updated_at'])
            messages.success(
                request,
                f'{booking.booking_no} completed successfully.',
                extra_tags='tenant',
            )
            return _tenant_redirect(request, 'iroad_tenants:tenant_operation_booking_list')
        finally:
            connection.set_schema_to_public()


class TenantOperationBookingEditView(View):
    template_name = 'iroad_tenants/Operation_management/Booking/Booking.html'

    def _load_booking(self, booking_id):
        return (
            TenantBooking.objects.select_related(
                'client_account',
                'price_list',
                'service_item',
                'route',
            )
            .filter(pk=booking_id)
            .first()
        )

    def get(self, request, booking_id):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        if not context.get('is_tenant_admin') and not context.get('can_view_booking'):
            messages.error(request, 'You do not have permission to edit Booking.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_dashboard')

        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            booking = self._load_booking(booking_id)
            if booking is None:
                messages.error(request, 'Booking not found.', extra_tags='tenant')
                return _tenant_redirect(request, 'iroad_tenants:tenant_operation_booking_list')
            context.update(_tenant_booking_form_options_context(tenant_registry, booking=booking))
            context.update(
                {
                    'preview_booking_no': booking.booking_no,
                    'booking_creation_date': booking.creation_date,
                    'booking_is_edit': True,
                    'booking': booking,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()

    def post(self, request, booking_id):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        if not context.get('is_tenant_admin') and not context.get('can_view_booking'):
            messages.error(request, 'You do not have permission to save Booking.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_dashboard')

        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            booking = self._load_booking(booking_id)
            if booking is None:
                messages.error(request, 'Booking not found.', extra_tags='tenant')
                return _tenant_redirect(request, 'iroad_tenants:tenant_operation_booking_list')

            available_tables = set(connection.introspection.table_names())
            has_table = available_tables.__contains__
            validation_errors, validated = _tenant_booking_validate_submission(
                request,
                booking_id=booking.booking_id,
                has_table=has_table,
            )
            if validation_errors:
                for error in validation_errors:
                    messages.error(request, error, extra_tags='tenant')
                return redirect('iroad_tenants:tenant_operation_booking_edit', booking_id=booking_id)

            client = validated['client']
            route = validated['route']
            route_direction = validated['route_direction']
            route_display = validated['route_display']

            booking.booking_date = parse_date((request.POST.get('booking_date') or '').strip()) or booking.booking_date
            booking.execution_date = validated['execution_date']
            booking.booking_status = (request.POST.get('booking_status') or TenantBooking.Status.DRAFT).strip()
            booking.client_account = client
            booking.price_list = validated['price_list']
            booking.service_item = validated['service_item']
            booking.route = route
            booking.route_direction = route_direction
            booking.route_display = route_display
            booking.order_type = (request.POST.get('order_type') or '').strip()
            booking.trip_type = (request.POST.get('trip_type') or '').strip()
            booking.sell_price = validated['derived_sell_price']
            booking.sourcing_mode = validated['sourcing_mode']
            booking.pod_type = (request.POST.get('pod_type') or '').strip()
            booking.pod_status = (request.POST.get('pod_status') or '').strip()
            for field_name, field_value in _tenant_booking_extra_payload(request).items():
                setattr(booking, field_name, field_value)
            if request.FILES.get('booking_attachment'):
                booking.booking_attachment = request.FILES['booking_attachment']
            booking.save()
            messages.success(request, f'{booking.booking_no} updated successfully.', extra_tags='tenant')
            return redirect('iroad_tenants:tenant_operation_booking_detail', booking_id=booking.booking_id)
        finally:
            connection.set_schema_to_public()


class TenantOperationBookingListView(View):
    """Render booking list page."""

    template_name = 'iroad_tenants/Operation_management/Booking/Booking-list.html'

    def get(self, request):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        if not context.get('is_tenant_admin') and not context.get('can_view_booking'):
            messages.error(request, 'You do not have permission to view Booking.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_dashboard')
        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            search_q = (request.GET.get('search') or '').strip()
            qs = TenantBooking.objects.select_related(
                'client_account',
                'price_list',
                'service_item',
                'assigned_truck',
                'assigned_driver',
            )
            if search_q:
                qs = qs.filter(
                    Q(booking_no__icontains=search_q)
                    | Q(client_account__display_name__icontains=search_q)
                    | Q(route_display__icontains=search_q)
                    | Q(price_list__price_list_code__icontains=search_q)
                )

            stats_qs = TenantBooking.objects.all()
            booking_page_obj = Paginator(qs.order_by('-created_at'), 10).get_page(
                request.GET.get('page') or 1
            )
            start_index = booking_page_obj.start_index() if booking_page_obj.paginator.count else 0
            booking_rows = []
            for idx, booking in enumerate(booking_page_obj.object_list, start=start_index):
                booking_rows.append(
                    {
                        'sn': idx,
                        'booking_id': booking.booking_id,
                        'booking_no': booking.booking_no,
                        'creation_date': booking.creation_date,
                        'booking_date': booking.booking_date,
                        'execution_date': booking.execution_date,
                        'client_name': booking.client_account.display_name,
                        'route_text': booking.route_display or '-',
                        'trip_type': booking.trip_type or '-',
                        'sales_order_no': booking.price_list.price_list_code if booking.price_list else '-',
                        'truck_no': booking.assigned_truck.truck_code if booking.assigned_truck else '-',
                        'sales_report': '-',
                        'sales_report_status': '-',
                    }
                )

            context.update(
                {
                    'booking_rows': booking_rows,
                    'booking_page_obj': booking_page_obj,
                    'booking_search_query': search_q,
                    'booking_stats': {
                        'total': stats_qs.count(),
                        'active': stats_qs.exclude(booking_status=TenantBooking.Status.CANCELLED).count(),
                        'executed': 0,
                        'cancelled': stats_qs.filter(booking_status=TenantBooking.Status.CANCELLED).count(),
                        'round': stats_qs.filter(trip_type='Round').count(),
                        'inbound': stats_qs.filter(route_direction='reverse').count(),
                        'outbound': stats_qs.filter(route_direction='forward').count(),
                        'unassigned_truck': stats_qs.filter(assigned_truck__isnull=True).count(),
                    },
                    'tenant_schema_name': tenant_registry.schema_name,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()


class TenantOperationBookingDetailView(View):
    """Render a full-page booking detail view."""

    template_name = 'iroad_tenants/Operation_management/Booking/Booking-detail.html'

    def get(self, request, booking_id):
        context = _tenant_context_from_session(request)
        if context is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        if not context.get('is_tenant_admin') and not context.get('can_view_booking'):
            messages.error(request, 'You do not have permission to view Booking.', extra_tags='tenant')
            return _tenant_redirect(request, 'iroad_tenants:tenant_dashboard')

        tenant_registry = _activate_tenant_workspace_schema(request)
        if tenant_registry is None:
            response = redirect('login')
            clear_tenant_portal_cookie(response, request=request)
            return response
        try:
            booking = (
                TenantBooking.objects.select_related(
                    'client_account',
                    'price_list',
                    'service_item',
                    'route',
                    'route__origin_point',
                    'route__destination_point',
                    'assigned_truck',
                    'assigned_driver',
                    'booking_line_backload_truck',
                    'booking_line_backload_driver',
                    'cargo',
                )
                .filter(pk=booking_id)
                .first()
            )
            if booking is None:
                messages.error(request, 'Booking not found.', extra_tags='tenant')
                return _tenant_redirect(request, 'iroad_tenants:tenant_operation_booking_list')

            line_status_values = _tenant_booking_line_status_map(booking)
            booking_lines = []
            if booking.trip_type:
                line_types = ['Outbound', 'Backload'] if booking.trip_type == 'Round' else ['Outbound']
                forward_route = ''
                reverse_route = ''
                if booking.route:
                    forward_route = (
                        f'{booking.route.origin_point.display_label} '
                        f'To {booking.route.destination_point.display_label}'
                    )
                    reverse_route = (
                        f'{booking.route.destination_point.display_label} '
                        f'To {booking.route.origin_point.display_label}'
                    )
                selected_route = booking.route_display or forward_route
                opposite_route = reverse_route if selected_route == forward_route else forward_route
                for idx, line_type in enumerate(line_types, start=1):
                    is_backload = line_type == 'Backload'
                    line_truck = booking.booking_line_backload_truck if is_backload else booking.assigned_truck
                    line_driver = booking.booking_line_backload_driver if is_backload else booking.assigned_driver
                    booking_lines.append(
                        {
                            'sn': idx,
                            'code': f'{line_type[:2].upper()}-{idx:03d}',
                            'type': line_type,
                            'status': line_status_values.get(line_type, 'Draft'),
                            'route': opposite_route if is_backload else selected_route,
                            'truck': line_truck.truck_code if line_truck else '-',
                            'driver': str(line_driver) if line_driver else '-',
                            'cod_amount': (
                                booking.booking_line_backload_cod_amount
                                if is_backload
                                else booking.booking_line_cod_amount
                            ),
                            'pod_doc_count': (
                                booking.booking_line_backload_pod_doc_count
                                if is_backload
                                else booking.booking_line_pod_doc_count
                            ),
                        }
                    )

            context.update(
                {
                    'booking': booking,
                    'booking_lines': booking_lines,
                    'tenant_schema_name': tenant_registry.schema_name,
                }
            )
            return render(request, self.template_name, context)
        finally:
            connection.set_schema_to_public()


